import java.util.Scanner;

public class Main {
    static final int N = 100;
    static final int D = 31;
    static final long MOD = 1000000007L;

    static int base, indexPos;
    static int[] digitsArr = new int[N];
    static long numberInput;

    static class MatrixType {
        long[][] mat = new long[D][D];

        MatrixType() {
            for (int i = 0; i <= base; i++) {
                for (int j = 0; j <= base; j++) {
                    mat[i][j] = 0;
                }
            }
        }

        MatrixType multiply(MatrixType other) {
            MatrixType res = new MatrixType();
            for (int i = 0; i <= base; i++) {
                for (int j = 0; j <= base; j++) {
                    for (int k = 0; k <= base; k++) {
                        res.mat[i][j] = (res.mat[i][j] + this.mat[i][k] * other.mat[k][j]) % MOD;
                    }
                }
            }
            return res;
        }
    }

    static MatrixType[] baseMats = new MatrixType[N];

    static MatrixType rotateShift(int shiftValue) {
        shiftValue = (shiftValue + base) % base;
        MatrixType m = new MatrixType();
        for (int i = 0; i < base; i++) {
            m.mat[i][(i + shiftValue) % base] = 1;
        }
        m.mat[base][base] = 1;
        return m;
    }

    static void initializeMatrices() {
        baseMats[0] = new MatrixType();
        for (int i = 1; i < base; i++) {
            baseMats[0].mat[i][i] = 1;
        }
        baseMats[0].mat[base][0] = 1;
        baseMats[0].mat[base][base] = 2;
        baseMats[0].mat[0][base] = -1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        numberInput = sc.nextLong();
        base = sc.nextInt();

        for (indexPos = 0; numberInput > 0; indexPos++, numberInput /= base) {
            digitsArr[indexPos] = (int)(numberInput % base);
        }

        initializeMatrices();

        for (int i = 1; i < indexPos; i++) {
            baseMats[i] = rotateShift(0);
            for (int j = 0; j < base; j++) {
                baseMats[i] = baseMats[i].multiply(baseMats[i - 1]).multiply(rotateShift(1));
            }
        }

        MatrixType answer = rotateShift(0);
        for (int i = indexPos - 1; i >= 0; i--) {
            for (int j = 0; j < digitsArr[i]; j++) {
                answer = answer.multiply(baseMats[i]).multiply(rotateShift(1));
            }
        }

        System.out.println((answer.mat[base][base] + MOD) % MOD);
        sc.close();
    }
}
